INSERT INTO `Course` (`courseCode`, `name`, `description`) VALUES
('MATH-123', 'Calculus', 'A course on calculus for math students.'),
('SWEN-344', 'Engineering of Web Based Software Systems', 'An introduction to the concepts, principles, and methods of engineering web-based software systems. Topics include: requirements, design, implementation, testing, and maintenance of web-based systems. Students will engineer a substantial web-based system as part of a team.'),
('SWEN-261', 'Introduction to Software Engineering', 'An introduction to the concepts, principles and methods of software engineering. The topics to be covered are: software process models, project management, requirements engineering, system models, architectural design, detailed design, implementation, integration, testing, and maintenance. Students will be expected to complete a software development project in a team.'),
('SWEN-561', 'Software Engineering Project I', 'This is the first of a two-course capstone project sequence. Student teams, with varied SE backgrounds and skills, will practice a disciplined and professional SE process to engineer and develop a software system for a real client. The project will require students to draw upon and integrate concepts and skills acquired in their previous SE courses. The project will span the entire SE development life-cycle, including: project planning and tracking, requirements elicitation and management, system design and modeling, implementation, and verification and validation. Students will be expected to produce all the necessary software engineering documents to support their project.'),
('SWEN-383', 'Software Design Principles and Patterns', 'This course focuses on the principles of quality software design and the study of established design patterns. Students will learn to analyze and evaluate the design of software systems and to apply design principles and patterns to the development of new software.'),
('SWEN-99', 'Undergraduate Cooperative Education Seminar', 'A seminar for undergraduate students preparing for their first cooperative education experience. Topics include resume writing, interview skills, professional conduct, and co-op policies and procedures.'),
('SWEN-101', 'Software Engineering Freshman Seminar', 'An introduction to the software engineering program, the department, and the university. Students will be introduced to the software engineering profession and the expectations of the program.'),
('SWEN-102', 'Software Engineering Seminar for Transfers', 'A seminar for students transferring into the software engineering program. This course will acclimate students with the software engineering department, curriculum, and policies.'),
('SWEN-250', 'Personal Software Engineering', 'This course introduces the foundational principles and practices of software engineering at the individual level. Topics include problem-solving, algorithm design, coding standards, debugging, version control, and unit testing.'),
('SWEN-256', 'Software Process and Project Management', 'This course covers the principles and practices of managing software projects and the processes used to develop high-quality software. Topics include project planning, scheduling, risk management, and process models like Agile and Waterfall.'),
('SWEN-262', 'Engineering of Software Subsystems', 'This course focuses on the design and implementation of complex software subsystems. Topics include architectural design, object-oriented design principles, and the use of frameworks and libraries to build robust and scalable software components.'),
('SWEN-331', 'Engineering Secure Software', 'This course provides a comprehensive overview of the principles and practices for engineering secure software systems. Topics include threat modeling, security requirements, secure design principles, defensive coding, and security testing.'),
('SWEN-340', 'Software Design for Computing Systems', 'This course examines the design of software for various computing systems, including embedded, mobile, and desktop applications. Students will learn to design software that meets specific performance, reliability, and usability requirements.'),
('SWEN-342', 'Engineering of Concurrent and Distributed Software Systems', 'This course covers the principles and techniques for designing and building concurrent and distributed software systems. Topics include threading, synchronization, message passing, and distributed architectures.'),
('SWEN-343', 'Engineering of Enterprise Software Systems', 'This course focuses on the design and development of large-scale enterprise software systems. Topics include enterprise application architecture, database integration, and the use of enterprise-level frameworks.'),
('SWEN-350', 'Software Process and Product Quality', 'This course examines the methods and techniques for ensuring the quality of software products and the processes used to develop them. Topics include quality assurance, quality control, software metrics, and process improvement.'),
('SWEN-352', 'Software Testing', 'This course provides a comprehensive introduction to software testing principles and practices. Topics include test planning, test case design, test automation, and various levels of testing such as unit, integration, and system testing.'),
('SWEN-440', 'Software System Requirements and Architecture', 'This course covers the critical early stages of software development, focusing on eliciting, analyzing, and documenting software requirements, and then using them to create and validate a high-level system architecture.'),
('SWEN-444', 'Human-Centered Requirements and Design', 'This course explores the integration of human-computer interaction (HCI) principles into the software engineering lifecycle. Topics include user research, usability testing, and the design of user-centered interfaces.'),
('SWEN-498', 'Software Engineering CIR Experience', 'A course that provides students with a culminating, integrative project experience in software engineering.'),
('SWEN-499', 'Software Engineering Co-op', 'The first cooperative education experience for software engineering students, providing practical, paid, full-time work experience in the field.'),
('SWEN-511', 'Software Engineering for Good', 'A project-based course where students apply software engineering principles to develop solutions for non-profit organizations or other social good initiatives.'),
('SWEN-514', 'Engineering Cloud Software Systems', 'This course covers the principles, architectures, and technologies for engineering software systems that are deployed and run on cloud computing platforms.'),
('SWEN-549', 'Software Engineering Design Seminar', 'A seminar course where students explore advanced topics in software design, present on current research, and critique the design of existing software systems.'),
('SWEN-563', 'Real-Time and Embedded Systems', 'This course covers the unique challenges and techniques for developing software for real-time and embedded systems, where timing constraints and resource limitations are critical.'),
('SWEN-601', 'Software Construction', 'This course focuses on the implementation phase of software development. Topics include advanced programming techniques, coding standards, debugging, and the use of development tools.'),
('SWEN-610', 'Foundations of Software Engineering', 'A graduate-level course covering the fundamental principles, processes, and practices of software engineering.'),
('SWEN-699', 'Graduate Co-op Experience', 'A cooperative education experience for graduate students, providing practical work experience in a professional software engineering environment.'),
('SWEN-746', 'Model-Driven Development', 'This course explores the use of models as the primary artifacts in the software development process. Topics include domain-specific languages, code generation, and model transformations.'),
('SWEN-755', 'Software Architecture', 'This course covers the principles and practices of software architecture, including architectural styles, design patterns, and methods for evaluating and documenting software architectures.'),
('SWEN-777', 'Software Quality Assurance', 'A graduate-level course on the principles and practices of software quality assurance. Topics include quality management, formal methods, inspections, and statistical quality control.'),
('SWEN-780', 'Capstone Research Project', 'A research-oriented capstone project where students work individually or in small teams to investigate a specific problem in software engineering and produce a scholarly paper or prototype.'),
('SWEN-781', 'Continuation of Capstone', 'A continuation of the capstone project, allowing students to further develop their research or project from the previous semester.'),
('SWEN-790', 'Thesis', 'Independent research work on a topic in software engineering, culminating in the writing of a master''s thesis.'),
('SWEN-791', 'Continuation of Thesis', 'A continuation of thesis research for students who require additional time to complete their work.'),
('SWEN-799', 'Independent Study', 'An opportunity for students to pursue an individual course of study on a topic of special interest under the guidance of a faculty member.');
